import math
from dataclasses import dataclass, asdict
from datetime import datetime, time, timedelta, timezone
from typing import Iterable, Optional
MIN_PER_YEAR = 365.0 * 24 * 60
_bx_refresh_table__IST = timezone(timedelta(hours=5, minutes=30))
SKIP_WINDOWS = [(time(0, 0), time(9, 25)), (time(11, 30), time(13, 0)), (time(14, 50), time.max)]

def _ncdf(x: float) -> float:
    return 0.5 * math.erfc(-x / math.sqrt(2.0))

def black76(F: float, K: float, T: float, sigma: float, df: float, is_call: bool) -> float:
    if T <= 0 or sigma <= 0:
        intrinsic = max(F - K, 0.0) if is_call else max(K - F, 0.0)
        return df * intrinsic
    s = sigma * math.sqrt(T)
    d1 = (math.log(F / K) + 0.5 * s * s) / s
    d2 = d1 - s
    if is_call:
        return df * (F * _ncdf(d1) - K * _ncdf(d2))
    return df * (K * _ncdf(-d2) - F * _ncdf(-d1))

@dataclass
class Leg:
    strike: float
    is_call: bool
    iv_pct: float
    bid: float
    ask: float
    ltp: float

@dataclass
class Level:
    price: float
    touches: int
    sources: list

@dataclass
class Row:
    strike: int
    side: str
    entry_ask: float
    trigger: Optional[int]
    target: Optional[float]
    status: str

def _round_to(x: float, step: float) -> float:
    return round(x / step) * step

def pick_level(levels: Iterable[Level], spot: float, above: bool, min_touches: int) -> tuple[Optional[Level], bool]:
    side = sorted((l for l in levels if (l.price > spot if above else l.price < spot)), key=lambda l: abs(l.price - spot))
    side = [l for l in side if set(l.sources) != {'vwap'}]
    strong = [l for l in side if l.touches >= min_touches]
    if strong:
        return (strong[0], False)
    if side:
        return (side[0], True)
    return (None, True)

def minutes_to_trigger(distance: float, atr: float, bar_minutes: int) -> float:
    if atr <= 0:
        return 15.0
    return min(max(abs(distance) / atr * bar_minutes, 5.0), 60.0)

def in_skip_window(now: datetime) -> bool:
    if now.tzinfo is not None:
        now = now.astimezone(_bx_refresh_table__IST)
    t = now.time()
    return any((a <= t <= b if b == time.max else a <= t < b for a, b in SKIP_WINDOWS))

def build_refresh_table(*, forward: float, T: float, df: float, candle_ref_price: float, resistances: list[Level], supports: list[Level], atr: float, bar_minutes: int, legs: list[Leg], snapshot_ms: int, candles_ms: int, now: datetime, buffer: float=5.0, round_step: float=5.0, min_touches: int=2, iv_shift_pts: float=0.0, max_skew_s: float=350.0) -> list[Row]:
    stale = abs(snapshot_ms - candles_ms) / 1000.0 > max_skew_s
    window_block = in_skip_window(now)
    basis = forward - candle_ref_price
    spot_in_level_space = candle_ref_price
    up, up_weak = pick_level(resistances, spot_in_level_space, True, min_touches)
    dn, dn_weak = pick_level(supports, spot_in_level_space, False, min_touches)
    rows: list[Row] = []
    for leg in sorted(legs, key=lambda l: (l.strike, not l.is_call)):
        side = 'CE' if leg.is_call else 'PE'
        lvl, weak = (up, up_weak) if leg.is_call else (dn, dn_weak)
        entry = leg.ask if leg.ask > 0 else leg.ltp
        if stale:
            rows.append(Row(int(leg.strike), side, entry, None, None, 'STALE'))
            continue
        if lvl is None:
            rows.append(Row(int(leg.strike), side, entry, None, None, 'NO_LEVEL'))
            continue
        trigger = _round_to(lvl.price + (buffer if leg.is_call else -buffer), round_step)
        F_target = trigger + basis
        mins = minutes_to_trigger(F_target - forward, atr, bar_minutes)
        T_target = max(T - mins / MIN_PER_YEAR, 1e-06)
        sigma = max(leg.iv_pct + iv_shift_pts, 0.1) / 100.0
        repriced = black76(F_target, leg.strike, T_target, sigma, df, leg.is_call)
        half_spread = max(leg.ask - leg.bid, 0.0) / 2.0 if leg.ask and leg.bid else 0.0
        target = round(repriced - half_spread, 2)
        status = 'OK'
        if weak:
            status = 'WEAK_LEVEL'
        if window_block:
            status = 'NO_TRADE_WINDOW'
        rows.append(Row(int(leg.strike), side, round(entry, 2), int(trigger), target, status))
    return rows

def to_markdown(rows: list[Row]) -> str:
    out = ['| Strike | Type | LTP (ask) | Trigger | Target | Status |', '|---|---|---|---|---|---|']
    for r in rows:
        trig = '—' if r.trigger is None else f'above {r.trigger:,}' if r.side == 'CE' else f'below {r.trigger:,}'
        tgt = '—' if r.target is None else f'{r.target:.0f}'
        out.append(f'| {r.strike} | {r.side} | {r.entry_ask:.2f} | {trig} | {tgt} | {r.status} |')
    return '\n'.join(out)

def to_compact(rows: list[Row]) -> str:
    out = ['| Strike | Type | LTP | Breakout Above |', '|---|---|---|---|']
    for r in rows:
        val = f'{r.target:.0f}' if r.target is not None and r.status == 'OK' else r.status
        out.append(f'| {r.strike} | {r.side} | {r.entry_ask:.2f} | {val} |')
    return '\n'.join(out)
class _BX_RT:
    Leg = Leg
    Level = Level
    build_refresh_table = staticmethod(build_refresh_table)
    in_skip_window = staticmethod(in_skip_window)
    to_compact = staticmethod(to_compact)


