import math
from decimal import ROUND_HALF_UP, Decimal
_MS_PER_DAY = 86400000

def is_number(v) -> bool:
    return isinstance(v, (int, float)) and (not isinstance(v, bool))

def is_finite(v) -> bool:
    return is_number(v) and math.isfinite(v)

def js_round(x: float) -> float:
    if not math.isfinite(x):
        return x
    if abs(x) >= 2 ** 52:
        return float(x)
    r = math.floor(x)
    return float(r + 1) if x - r >= 0.5 else float(r)

def to_fixed(x: float, digits: int) -> str:
    if math.isnan(x):
        return 'NaN'
    if math.isinf(x):
        return 'Infinity' if x > 0 else '-Infinity'
    if x == 0:
        x = 0.0
    q = Decimal(x).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_UP)
    s = format(q, 'f')
    return s

def js_str(v) -> str:
    if v is None:
        return 'null'
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return _number_to_string(v)
    return str(v)

def _number_to_string(x: float) -> str:
    if math.isnan(x):
        return 'NaN'
    if x == 0:
        return '0'
    if math.isinf(x):
        return 'Infinity' if x > 0 else '-Infinity'
    if x < 0:
        return '-' + _number_to_string(-x)
    sign_, digits_t, exp = Decimal(repr(x)).as_tuple()
    digits = ''.join(map(str, digits_t)).rstrip('0') or '0'
    k = len(digits)
    n = exp + len(digits_t)
    if k <= n <= 21:
        return digits + '0' * (n - k)
    if 0 < n <= 21:
        return digits[:n] + '.' + digits[n:]
    if -6 < n <= 0:
        return '0.' + '0' * -n + digits
    e = n - 1
    es = ('+' if e > 0 else '-') + str(abs(e))
    return (digits if k == 1 else digits[0] + '.' + digits[1:]) + 'e' + es
_JS_WS_POINTS = frozenset((9, 10, 11, 12, 13, 32, 160, 5760, 8192, 8193, 8194, 8195, 8196, 8197, 8198, 8199, 8200, 8201, 8202, 8232, 8233, 8239, 8287, 12288, 65279))

def is_js_whitespace(c: str) -> bool:
    return int.from_bytes(c.encode('utf-32-be', 'surrogatepass'), 'big') in _JS_WS_POINTS

def strip_where(s: str, pred) -> str:
    i, j = (0, len(s))
    while i < j and pred(s[i]):
        i += 1
    while j > i and pred(s[j - 1]):
        j -= 1
    return s[i:j]

def js_number(s: str) -> float:
    t = strip_where(s, is_js_whitespace)
    if t == '':
        return 0.0
    low = t.lower()
    if low in ('infinity', '+infinity'):
        return math.inf if t in ('Infinity', '+Infinity') else math.nan
    if low == '-infinity':
        return -math.inf if t == '-Infinity' else math.nan
    if low.startswith(('0x', '0o', '0b')):
        base = {'x': 16, 'o': 8, 'b': 2}[low[1]]
        try:
            return float(int(t[2:], base))
        except ValueError:
            return math.nan
    if '_' in t or low in ('nan', 'inf', '+inf', '-inf', '+nan', '-nan'):
        return math.nan
    try:
        return float(t)
    except ValueError:
        return math.nan

def _is_array_index(k: str) -> bool:
    if k == '0':
        return True
    if not k or k[0] == '0' or (not k.isdigit()) or (not k.isascii()):
        return False
    return int(k) < 2 ** 32 - 1

def object_keys(d: dict) -> list:
    idx = sorted((k for k in d if _is_array_index(k)), key=int)
    rest = [k for k in d if not _is_array_index(k)]
    return idx + rest

def _days_from_civil(y: int, m: int, d: int) -> int:
    y -= m <= 2
    era = y // 400
    yoe = y - era * 400
    doy = (153 * (m + (-3 if m > 2 else 9)) + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468

def date_utc(year: int, month0: int, day: int, h: int=0, mi: int=0, s: int=0) -> int:
    if 0 <= year <= 99:
        year += 1900
    return civil_ms(year, month0, day, h, mi, s)

def civil_ms(year: int, month0: int, day: int, h: int=0, mi: int=0, s: int=0) -> int:
    ym = year + month0 // 12
    mn = month0 % 12
    days = _days_from_civil(ym, mn + 1, 1) + (day - 1)
    return days * _MS_PER_DAY + ((h * 60 + mi) * 60 + s) * 1000

def iso_of(epoch_ms: float) -> str:
    ms = int(epoch_ms)
    days, rem = divmod(ms, _MS_PER_DAY)
    z = days + 719468
    era = z // 146097
    doe = z - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    y = yoe + era * 400
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    d = doy - (153 * mp + 2) // 5 + 1
    m = mp + (3 if mp < 10 else -9)
    y += m <= 2
    hh, rem = divmod(rem, 3600000)
    mm, rem = divmod(rem, 60000)
    ss, msr = divmod(rem, 1000)
    return '%04d-%02d-%02dT%02d:%02d:%02d.%03dZ' % (y, m, d, hh, mm, ss, msr)

def js_sum(values):
    t = 0
    for v in values:
        t = t + v
    return t

class _Undefined:
    _inst = None

    def __new__(cls):
        if cls._inst is None:
            cls._inst = super().__new__(cls)
        return cls._inst

    def __repr__(self):
        return 'undefined'

    def __bool__(self):
        return False
UNDEFINED = _Undefined()

def js_truthy(v) -> bool:
    if v is None or v is UNDEFINED or v is False:
        return False
    if is_number(v):
        return v == v and v != 0
    if isinstance(v, str):
        return v != ''
    return True

def is_js_object(v) -> bool:
    return isinstance(v, (dict, list))

def js_get(o, key):
    if isinstance(o, dict):
        return o[key] if key in o else UNDEFINED
    if isinstance(o, list) and key.isdigit():
        i = int(key)
        return o[i] if i < len(o) else UNDEFINED
    return UNDEFINED

def js_max(*xs):
    if not xs:
        return -math.inf
    if any((isinstance(x, float) and math.isnan(x) for x in xs)):
        return math.nan
    return max(xs)

def js_min(*xs):
    if not xs:
        return math.inf
    if any((isinstance(x, float) and math.isnan(x) for x in xs)):
        return math.nan
    return min(xs)

