# module: engine/sensex/integrity.py
# ----------------------------------------------------------------------
def _report(findings, checked_at_ms):
    return {'ok': not any((f['severity'] == 'block' for f in findings)), 'findings': findings, 'checkedAtMs': checked_at_ms}

def check_quote(q: dict, now_ms, max_age_ms) -> dict:
    f = []
    sid = '%s:%s' % (q['segment'], q['securityId'])
    if not is_finite(q['ltp']):
        f.append({'severity': 'block', 'findingCode': 'QUOTE_NO_LTP', 'message': 'No usable last_price for %s.' % sid})
    if q['lastTradeTimeMs'] is None:
        f.append({'severity': 'warn', 'findingCode': 'QUOTE_NO_TRADE_TIME', 'message': '%s has no last_trade_time (never traded, or the 01/01/1980 sentinel). Staleness cannot be established from the vendor clock.' % sid})
    else:
        age = now_ms - q['lastTradeTimeMs']
        if age > max_age_ms:
            f.append({'severity': 'warn', 'findingCode': 'QUOTE_STALE', 'message': '%s last traded %ss ago, beyond the %ss freshness window.' % (sid, to_fixed(age / 1000, 1), to_fixed(max_age_ms / 1000, 1))})
    if q['depth']:
        bid = next((l for l in q['depth']['buy'] if l['price'] > 0 and l['quantity'] > 0), None)
        ask = next((l for l in q['depth']['sell'] if l['price'] > 0 and l['quantity'] > 0), None)
        if bid and ask and (bid['price'] >= ask['price']):
            f.append({'severity': 'block', 'findingCode': 'QUOTE_CROSSED', 'message': 'Crossed book on %s: bid %s >= ask %s. Refusing to derive liquidity from it.' % (sid, js_str(bid['price']), js_str(ask['price']))})
        if not bid or not ask:
            f.append({'severity': 'warn', 'findingCode': 'QUOTE_ONE_SIDED', 'message': 'One-sided or empty book on %s.' % sid})
    if len(q['quarantined']) > 0:
        f.append({'severity': 'warn', 'findingCode': 'QUOTE_QUARANTINED_FIELDS', 'message': 'Quarantined unparseable fields: %s.' % ', '.join(q['quarantined'].keys())})
    return _report(f, now_ms)

def check_chain(chain: dict, now_ms) -> dict:
    f = []
    if len(chain['strikes']) == 0:
        f.append({'severity': 'block', 'findingCode': 'CHAIN_EMPTY', 'message': 'Option chain for %s %s has no strikes.' % (chain['underlying'], chain['expiry'])})
        return _report(f, now_ms)
    both = crossed = zero = suspect = 0
    for s in chain['strikes']:
        if s['ce'] and s['pe']:
            both += 1
        for leg in (s['ce'], s['pe']):
            if not leg:
                continue
            if leg['lastPrice'] is not None and leg['lastPrice'] <= 0:
                zero += 1
            b, a = (leg['topBidPrice'], leg['topAskPrice'])
            if b is not None and a is not None and (b > 0) and (a > 0) and (b >= a):
                crossed += 1
            iv = leg['vendorQuarantined']['impliedVolatility']
            if iv is None or iv <= 0 or iv > 60:
                suspect += 1
    if both < 2:
        f.append({'severity': 'block', 'findingCode': 'CHAIN_INSUFFICIENT_PAIRS', 'message': 'Only %d strike(s) have both a CE and a PE. Put-call parity needs at least 2 complete pairs to recover a forward.' % both})
    if crossed > 0:
        f.append({'severity': 'warn', 'findingCode': 'CHAIN_CROSSED_LEGS', 'message': '%d leg(s) show a crossed top-of-book; they are excluded from parity.' % crossed})
    if zero > 0:
        f.append({'severity': 'warn', 'findingCode': 'CHAIN_ZERO_PRICES', 'message': '%d leg(s) have a non-positive last price.' % zero})
    total = sum((int(bool(s['ce'])) + int(bool(s['pe'])) for s in chain['strikes']))
    if total > 0:
        pct = suspect / total * 100
        f.append({'severity': 'info', 'findingCode': 'VENDOR_IV_QUARANTINED', 'message': '%d/%d legs (%s%%) carry vendor IV that is zero, missing or >60%%. All vendor IV and Greeks are quarantined regardless; this server computes its own.' % (suspect, total, to_fixed(pct, 1))})
    if chain['underlyingLtpDoNotUseAsSpot'] is not None:
        f.append({'severity': 'info', 'findingCode': 'CHAIN_CARRIES_INDEX_LTP', 'message': 'Chain reports underlying last_price %s. This is the INDEX LTP and is never used as spot for option maths.' % js_str(chain['underlyingLtpDoNotUseAsSpot'])})
    return _report(f, now_ms)

def check_snapshot_skew(a: dict, b: dict, max_skew_ms) -> dict:
    skew = abs(a['epochMs'] - b['epochMs'])
    same = a['fetchId'] == b['fetchId']
    if same:
        return {'ok': True, 'skewMs': skew, 'sameFetch': same, 'message': 'Single atomic fetch.'}
    if skew <= max_skew_ms:
        return {'ok': True, 'skewMs': skew, 'sameFetch': same, 'message': 'Distinct fetches %sms apart, inside the %sms window.' % (js_str(skew), js_str(max_skew_ms))}
    return {'ok': False, 'skewMs': skew, 'sameFetch': same, 'message': 'Snapshot skew %sms exceeds the %sms limit. The chain and the futures leg are not one snapshot; mixing them would price across two timestamps.' % (js_str(skew), js_str(max_skew_ms))}

# ----------------------------------------------------------------------
# module: engine/sensex/pricing_bridge.py
# ----------------------------------------------------------------------
MAX_MID_SPREAD_FRAC = 0.05

def fair_price(leg):
    if not leg:
        return None
    b, a = (leg['topBidPrice'], leg['topAskPrice'])
    if b is not None and a is not None and (b > 0) and (a > 0) and (a >= b):
        mid = (a + b) / 2
        if (a - b) / mid <= MAX_MID_SPREAD_FRAC:
            return {'price': mid, 'source': 'mid'}
    l = leg['lastPrice']
    return {'price': l, 'source': 'ltp'} if is_number(l) and l > 0 else None

def _nearest_strike(strikes, reference):
    if not strikes:
        return None
    best = strikes[0]
    for k in strikes[1:]:
        if abs(k - reference) < abs(best - reference):
            best = k
    return best

def attach_pricing(chain: dict, futures, risk_free_rate: float, max_snapshot_skew_ms: float, atm_hint=None, band_pct=None, thresholds=None, now_ms=None, futures_expiry=None) -> dict:
    skew_ms, same_fetch = (0, True)
    if futures:
        skew = check_snapshot_skew({'fetchId': chain['provenance']['fetchId'], 'epochMs': chain['provenance']['epochMs']}, {'fetchId': futures['provenance']['fetchId'], 'epochMs': futures['provenance']['epochMs']}, max_snapshot_skew_ms)
        if not skew['ok']:
            raise SnapshotSkewError(skew['message'], {'chainFetchId': chain['provenance']['fetchId'], 'futuresFetchId': futures['provenance']['fetchId'], 'skewMs': skew['skewMs'], 'maxSkewMs': max_snapshot_skew_ms})
        skew_ms, same_fetch = (skew['skewMs'], skew['sameFetch'])
    as_of = now_ms if now_ms is not None else chain['provenance']['epochMs']
    T = year_fraction_to_expiry(as_of, chain['expiry'])
    if not T > 0:
        raise PricingValidationError('Expiry %s is at or before the snapshot time — T = %s. Cannot price an expired contract.' % (chain['expiry'], js_str(T)), {'expiry': chain['expiry'], 'asOfMs': as_of, 'T': T})
    r = risk_free_rate
    DF = discount_factor(r, T)
    legs = []
    for s in chain['strikes']:
        c, p = (fair_price(s['ce']), fair_price(s['pe']))
        if not c or not p:
            continue
        legs.append({'strike': s['strike'], 'callPrice': c['price'], 'putPrice': p['price']})
    if len(legs) < 2:
        raise GateBlockedError(['Only %d strike(s) have a usable CE/PE pair. Put-call parity needs at least 2 to recover a forward.' % len(legs)])
    paired = [l['strike'] for l in legs]
    atm_from_parity = paired[len(paired) // 2]
    best = float('inf')
    for l in legs:
        d = abs(l['callPrice'] - l['putPrice'])
        if d < best:
            best, atm_from_parity = (d, l['strike'])
    hint = atm_hint if atm_hint is not None else atm_from_parity
    fd = parity_forward(legs, hint, r, T, band_pct=0.015 if band_pct is None else band_pct)
    listed = futures['ltp'] if futures and is_finite(futures['ltp']) else None
    gap = year_fraction_to_expiry(as_of, futures_expiry) - T if futures_expiry and futures_expiry != chain['expiry'] else 0
    gate = check_gate(parity_forward=fd['forward'], listed_future=listed, per_strike_spread=fd['spread'], index_ltp=chain['underlyingLtpDoNotUseAsSpot'], slope_within_tolerance=fd['slopeDiagnostic']['withinTolerance'], slope_relative_error=fd['slopeDiagnostic']['relativeError'], future_expiry_gap_years=gap, thresholds=thresholds)
    if gate['blocked']:
        raise GateBlockedError(gate['reasons'], {'parityForward': fd['forward'], 'listedFuture': futures['ltp'] if futures else None, 'perStrikeSpread': fd['spread'], 'divergenceVsFuture': gate['divergenceVsFuture'], 'impliedCarryAnnual': gate['impliedCarryAnnual'], 'futureCheckMode': gate['futureCheckMode'], 'futuresExpiry': futures_expiry, 'indexDivergence': gate['indexDivergence'], 'thresholds': gate['thresholds']})
    F = fd['forward']
    priced = []
    for s in chain['strikes']:
        for typ in ('CE', 'PE'):
            leg = s['ce'] if typ == 'CE' else s['pe']
            if not leg or not is_number(leg['lastPrice']) or (not leg['lastPrice'] > 0):
                continue
            fp = fair_price(leg)
            sigma = b76_iv(fp['price'] if fp else leg['lastPrice'], F, s['strike'], T, r, typ)
            g = None if sigma is None or sigma <= 0 else b76_greeks(F, s['strike'], T, sigma, r, typ)
            vendor = leg['vendorQuarantined']['impliedVolatility']
            ours = None if sigma is None else sigma * 100
            priced.append({'strike': s['strike'], 'type': typ, 'securityId': leg['securityId'], 'marketPrice': leg['lastPrice'], 'ivPct': ours, 'delta': g['delta'] if g else None, 'gamma': g['gamma'] if g else None, 'vega': g['vega'] if g else None, 'theta': g['theta'] if g else None, 'rho': g['rho'] if g else None, 'moneyness': s['strike'] / F, 'vendorIvPct': vendor, 'vendorIvDeltaPct': ours - vendor if ours is not None and vendor is not None else None})
    return {'asOfMs': as_of, 'expiry': chain['expiry'], 'T': T, 'calendarDaysToExpiry': T * 365, 'riskFreeRate': r, 'discountFactor': DF, 'forward': F, 'forwardDetail': fd, 'listedFuture': listed, 'indexLtpDoNotUseAsSpot': chain['underlyingLtpDoNotUseAsSpot'], 'gate': gate, 'legs': priced, 'atmStrike': _nearest_strike(paired, F), 'snapshot': {'chainFetchId': chain['provenance']['fetchId'], 'futuresFetchId': futures['provenance']['fetchId'] if futures else None, 'skewMs': skew_ms, 'sameFetch': same_fetch}}

# ----------------------------------------------------------------------
# module: engine/sensex/levels.py
# ----------------------------------------------------------------------
_bx_levels__IST_OFFSET_MS = (5 * 60 + 30) * 60 * 1000
STRUCTURAL = {'previous_session_high', 'previous_session_low', 'opening_range_high', 'opening_range_low', 'vwap'}

def ist_date_of(epoch_ms):
    return iso_of(epoch_ms + _bx_levels__IST_OFFSET_MS)[:10]

def ist_time_of(epoch_ms):
    return iso_of(epoch_ms + _bx_levels__IST_OFFSET_MS)[11:16]

def true_ranges(candles):
    tr = []
    for i, c in enumerate(candles):
        if i == 0:
            tr.append(c['high'] - c['low'])
            continue
        pc = candles[i - 1]['close']
        tr.append(js_max(c['high'] - c['low'], abs(c['high'] - pc), abs(c['low'] - pc)))
    return tr

def wilder_smooth(values, period):
    out = [None] * len(values)
    if period <= 0 or len(values) < period:
        return out
    s = 0
    for i in range(period):
        s += values[i]
    prev = s / period
    out[period - 1] = prev
    for i in range(period, len(values)):
        prev = prev + (values[i] - prev) / period
        out[i] = prev
    return out

def atr(candles, period=14):
    if len(candles) < period + 1:
        return None
    s = wilder_smooth(true_ranges(candles), period)
    return s[-1] if s else None

def vwap(candles):
    pv = 0
    vol = 0
    for c in candles:
        v = c['volume'] if c['volume'] is not None else 0
        if v <= 0:
            continue
        pv += (c['high'] + c['low'] + c['close']) / 3 * v
        vol += v
    return pv / vol if vol > 0 else None

def session_vwap(candles):
    if not candles:
        return None
    last = ist_date_of(candles[-1]['timestampMs'])
    return vwap([c for c in candles if ist_date_of(c['timestampMs']) == last])

def sessions(candles):
    by_date = {}
    for c in candles:
        by_date.setdefault(ist_date_of(c['timestampMs']), []).append(c)
    out = []
    for date, bars in by_date.items():
        high, low, volume, has_vol = (float('-inf'), float('inf'), 0, False)
        for b in bars:
            if b['high'] > high:
                high = b['high']
            if b['low'] < low:
                low = b['low']
            if b['volume'] is not None:
                volume += b['volume']
                has_vol = True
        out.append({'date': date, 'open': bars[0]['open'], 'high': high, 'low': low, 'close': bars[-1]['close'], 'volume': volume if has_vol else None, 'bars': len(bars)})
    out.sort(key=lambda s: s['date'])
    return out

def opening_range(candles, minutes=15):
    if not candles:
        return None
    last = ist_date_of(candles[-1]['timestampMs'])
    day = [c for c in candles if ist_date_of(c['timestampMs']) == last]
    if not day:
        return None
    start = day[0]['timestampMs']
    win = [c for c in day if c['timestampMs'] < start + minutes * 60000]
    if not win:
        return None
    high, low = (float('-inf'), float('inf'))
    for b in win:
        if b['high'] > high:
            high = b['high']
        if b['low'] < low:
            low = b['low']
    return {'high': high, 'low': low, 'bars': len(win), 'fromIst': ist_time_of(win[0]['timestampMs']), 'toIst': ist_time_of(win[-1]['timestampMs'])}

def find_swing_points(candles, lookback=2):
    out = []
    if len(candles) < lookback * 2 + 1:
        return out
    for i in range(lookback, len(candles) - lookback):
        c = candles[i]
        is_high = is_low = True
        for j in range(i - lookback, i + lookback + 1):
            if j == i:
                continue
            if candles[j]['high'] >= c['high']:
                is_high = False
            if candles[j]['low'] <= c['low']:
                is_low = False
        if is_high:
            out.append({'index': i, 'timestampMs': c['timestampMs'], 'istTime': ist_time_of(c['timestampMs']), 'price': c['high'], 'kind': 'high'})
        elif is_low:
            out.append({'index': i, 'timestampMs': c['timestampMs'], 'istTime': ist_time_of(c['timestampMs']), 'price': c['low'], 'kind': 'low'})
    return out

def aggregate_candles(candles, minutes):
    if not candles or minutes <= 1:
        return candles
    bucket_ms = minutes * 60000
    out, bucket = ([], [])
    start = candles[0]['timestampMs'] // bucket_ms * bucket_ms

    def flush():
        if not bucket:
            return
        high, low, volume, has_vol = (float('-inf'), float('inf'), 0, False)
        for b in bucket:
            if b['high'] > high:
                high = b['high']
            if b['low'] < low:
                low = b['low']
            if b['volume'] is not None:
                volume += b['volume']
                has_vol = True
        out.append({'timestampMs': bucket[0]['timestampMs'], 'open': bucket[0]['open'], 'high': high, 'low': low, 'close': bucket[-1]['close'], 'volume': volume if has_vol else None, 'openInterest': bucket[-1]['openInterest']})
        bucket.clear()
    for c in candles:
        this = c['timestampMs'] // bucket_ms * bucket_ms
        if this != start:
            flush()
            start = this
        bucket.append(c)
    flush()
    return out

def collect_candidates(candles, swing_lookback, consolidation_window):
    out = []
    sess = sessions(candles)
    current = sess[-1] if sess else None
    previous = sess[-2] if len(sess) > 1 else None
    orr = opening_range(candles, 15)
    for s in find_swing_points(candles, swing_lookback):
        out.append({'price': s['price'], 'source': 'swing_high' if s['kind'] == 'high' else 'swing_low'})
    if current:
        out.append({'price': current['high'], 'source': 'session_high'})
        out.append({'price': current['low'], 'source': 'session_low'})
    if previous:
        out.append({'price': previous['high'], 'source': 'previous_session_high'})
        out.append({'price': previous['low'], 'source': 'previous_session_low'})
    if orr:
        out.append({'price': orr['high'], 'source': 'opening_range_high'})
        out.append({'price': orr['low'], 'source': 'opening_range_low'})
    v = session_vwap(candles)
    if v is not None:
        out.append({'price': v, 'source': 'vwap'})
    window = candles[-min(consolidation_window, len(candles)):] if candles else []
    if window:
        hi, lo = (float('-inf'), float('inf'))
        for c in window:
            if c['high'] > hi:
                hi = c['high']
            if c['low'] < lo:
                lo = c['low']
        out.append({'price': hi, 'source': 'consolidation_high'})
        out.append({'price': lo, 'source': 'consolidation_low'})
    return [c for c in out if is_finite(c['price'])]

def count_touches(candles, price, tolerance, kind):
    n = 0
    for c in candles:
        probe = c['high'] if kind == 'resistance' else c['low']
        if abs(probe - price) <= tolerance:
            n += 1
    return n

def _cluster(cands, tolerance):
    clusters = []
    for c in sorted(cands, key=lambda x: x['price']):
        if clusters:
            last = clusters[-1]
            mean = js_sum(last['prices']) / len(last['prices'])
            if abs(c['price'] - mean) <= tolerance:
                last['prices'].append(c['price'])
                if c['source'] not in last['sources']:
                    last['sources'].append(c['source'])
                continue
        clusters.append({'prices': [c['price']], 'sources': [c['source']]})
    return clusters

def _bx_levels___round_to(value, step):
    if not step or step <= 0:
        return value
    return js_round(value / step) * step

def derive_levels(candles, spot, confirmation_buffer=None, tolerance=None, min_touches=None, swing_lookback=None, consolidation_window=None, round_to=None) -> dict:
    diagnostics = []
    a = atr(candles, 14)
    buffer = 5 if confirmation_buffer is None else confirmation_buffer
    min_t = 2 if min_touches is None else min_touches
    look = 2 if swing_lookback is None else swing_lookback
    cwin = 20 if consolidation_window is None else consolidation_window
    rnd = 5 if round_to is None else round_to
    tol = tolerance if tolerance is not None else js_max(spot * 0.0003, a * 0.25 if a is not None else 0, 2)
    empty = {'spot': spot, 'atr14': a, 'toleranceUsed': tol, 'confirmationBuffer': buffer, 'resistance': None, 'support': None, 'breakoutAbove': None, 'breakdownBelow': None, 'nextResistance': None, 'nextSupport': None, 'allResistance': [], 'allSupport': [], 'rejected': [], 'barsAnalyzed': len(candles), 'timeframeMinutes': None, 'diagnostics': diagnostics}
    if not candles:
        diagnostics.append('No candles supplied — no level can be derived.')
        return empty
    if not is_finite(spot) or spot <= 0:
        diagnostics.append('Spot price unavailable — cannot place levels relative to price.')
        return empty
    tf_ms = candles[1]['timestampMs'] - candles[0]['timestampMs'] if len(candles) > 1 else None
    tf_min = js_round(tf_ms / 60000) if tf_ms else None
    cands = collect_candidates(candles, look, cwin)
    if not cands:
        diagnostics.append('No candidate levels found in the series.')
        return {**empty, 'timeframeMinutes': tf_min}
    confirmed, rejected = ([], [])
    for cl in _cluster(cands, tol):
        mean = js_sum(cl['prices']) / len(cl['prices'])
        kind = 'resistance' if mean > spot else 'support'
        touches = count_touches(candles, mean, tol, kind)
        structural = any((s in STRUCTURAL for s in cl['sources']))
        if not structural and touches < min_t:
            rejected.append({'price': mean, 'sources': cl['sources'], 'touches': touches, 'reason': 'Isolated spike: %d touch(es) within %s pts, below the %s required for a non-structural level.' % (touches, to_fixed(tol, 1), js_str(min_t))})
            continue
        distance = mean - spot
        confirmed.append({'price': mean, 'kind': kind, 'touches': touches, 'sources': cl['sources'], 'structural': structural, 'tolerance': tol, 'distanceFromSpot': distance, 'distanceInAtr': distance / a if a and a > 0 else None, 'note': 'Structural level (%s), %d touch(es).' % (', '.join(cl['sources']), touches) if structural else 'Confirmed by %d touches within %s pts.' % (touches, to_fixed(tol, 1))})
    all_res = sorted((l for l in confirmed if l['kind'] == 'resistance'), key=lambda l: l['price'])
    all_sup = sorted((l for l in confirmed if l['kind'] == 'support'), key=lambda l: -l['price'])
    res = all_res[0] if all_res else None
    sup = all_sup[0] if all_sup else None
    if not res:
        diagnostics.append('No confirmed resistance above spot. Price may be at the session extreme, or every candidate above spot was an isolated spike.')
    if not sup:
        diagnostics.append('No confirmed support below spot. Price may be at the session extreme, or every candidate below spot was an isolated spike.')
    diagnostics.append('%d level(s) confirmed, %d rejected as spikes.' % (len(confirmed), len(rejected)))
    return {'spot': spot, 'atr14': a, 'toleranceUsed': tol, 'confirmationBuffer': buffer, 'resistance': res, 'support': sup, 'breakoutAbove': _bx_levels___round_to(res['price'] + buffer, rnd) if res else None, 'breakdownBelow': _bx_levels___round_to(sup['price'] - buffer, rnd) if sup else None, 'nextResistance': all_res[1] if len(all_res) > 1 else None, 'nextSupport': all_sup[1] if len(all_sup) > 1 else None, 'allResistance': all_res, 'allSupport': all_sup, 'rejected': rejected, 'barsAnalyzed': len(candles), 'timeframeMinutes': tf_min, 'diagnostics': diagnostics}
_NOTE = 'Premium targets are delta/gamma projections from current spot, not quotes. Underlying levels come from confirmed price action.'

def project_premium(entry, delta, gamma, move):
    if delta is None:
        return None
    second = 0.5 * gamma * move * move if gamma is not None else 0
    return js_max(0, entry + delta * move + second)

def build_trade_plan(side, levels, entry, delta, gamma):
    a = levels['atr14']
    spot = levels['spot']
    if side == 'CE':
        if levels['breakoutAbove'] is None:
            return None
        trig = levels['breakoutAbove']
        nr, sp = (levels['nextResistance'], levels['support'])
        target = nr['price'] if nr else trig + a if a else trig * 1.002
        tsrc = 'Next confirmed resistance (%d touches).' % nr['touches'] if nr else 'No further resistance confirmed; projected one ATR above the trigger.'
        stop = sp['price'] if sp else trig - a if a else trig * 0.998
        ssrc = 'Nearest confirmed support (%d touches).' % sp['touches'] if sp else 'No confirmed support; projected one ATR below the trigger.'
        rr = abs((target - trig) / (trig - stop)) if trig - stop != 0 else None
    else:
        if levels['breakdownBelow'] is None:
            return None
        trig = levels['breakdownBelow']
        ns, rs = (levels['nextSupport'], levels['resistance'])
        target = ns['price'] if ns else trig - a if a else trig * 0.998
        tsrc = 'Next confirmed support (%d touches).' % ns['touches'] if ns else 'No further support confirmed; projected one ATR below the trigger.'
        stop = rs['price'] if rs else trig + a if a else trig * 1.002
        ssrc = 'Nearest confirmed resistance (%d touches).' % rs['touches'] if rs else 'No confirmed resistance; projected one ATR above the trigger.'
        rr = abs((trig - target) / (stop - trig)) if stop - trig != 0 else None
    return {'side': side, 'triggerLevel': trig, 'targetLevel': target, 'targetSource': tsrc, 'stopLevel': stop, 'stopSource': ssrc, 'entryPremium': entry, 'triggerPremium': project_premium(entry, delta, gamma, trig - spot), 'targetPremium': project_premium(entry, delta, gamma, target - spot), 'stopPremium': project_premium(entry, delta, gamma, stop - spot), 'riskRewardRatio': rr, 'note': _NOTE}

