import math
BLANK_TABLE = '| Strike | Type | LTP | Breakout Above |\n|---|---|---|---|\n| — | — | — | — |'

def build_scan(*, raw_chain, raw_futures, candles, expiry, strikes, chain_received_ms, futures_received_ms, futures_security_id='FUT', futures_expiry=None, risk_free_rate=0.065, max_snapshot_skew_ms=3000, chain_fetch_id='chain', futures_fetch_id='futures', detail_out: dict | None=None) -> dict:
    d = detail_out if detail_out is not None else {}
    chain = normalize_chain(raw_chain, 'SENSEX', 51, 'IDX_I', expiry, chain_fetch_id, chain_received_ms, '/optionchain')
    futures = None
    if raw_futures is not None:
        futures = normalize_quote(raw_futures, str(futures_security_id), 'BSE_FNO', futures_fetch_id, futures_received_ms, '/marketfeed/quote')
    d.update(chain=chain, futures=futures)
    try:
        p = attach_pricing(chain, futures, risk_free_rate, max_snapshot_skew_ms, futures_expiry=futures_expiry)
    except GateBlockedError as e:
        d['gateError'] = {'type': 'GateBlockedError', 'reasons': e.reasons, 'details': e.details}
        return {'status': 'BLOCKED', 'reasons': e.reasons}
    except SnapshotSkewError as e:
        d['gateError'] = {'type': 'SnapshotSkewError', 'reasons': [e.message], 'details': e.details}
        return {'status': 'BLOCKED', 'reasons': [e.message]}
    except PricingValidationError as e:
        d['gateError'] = {'type': 'ValidationError', 'reasons': [e.message], 'details': e.details}
        return {'status': 'ERROR', 'reasons': [e.message]}
    d['pricing'] = p
    index_ltp = chain['underlyingLtpDoNotUseAsSpot']
    spot = index_ltp if index_ltp is not None else math.nan
    lv = derive_levels(candles, spot, confirmation_buffer=5, min_touches=2, round_to=5)
    d['levels'] = lv
    by_key = {(l['strike'], l['type']): l for l in p['legs']}
    chain_legs = {s['strike']: s for s in chain['strikes']}
    legs, excluded = ([], [])
    for k in strikes:
        for typ in ('CE', 'PE'):
            priced = by_key.get((k, typ))
            raw = chain_legs.get(k, {}).get('ce' if typ == 'CE' else 'pe')
            if priced is None or priced['ivPct'] is None or raw is None:
                excluded.append({'strike': k, 'type': typ, 'reason': 'no priced leg' if priced is None else 'no IV (outside no-arbitrage bounds)' if priced['ivPct'] is None else 'no chain leg'})
                continue
            legs.append({'strike': k, 'isCall': typ == 'CE', 'ivPct': priced['ivPct'], 'bid': raw['topBidPrice'] if raw['topBidPrice'] is not None else 0, 'ask': raw['topAskPrice'] if raw['topAskPrice'] is not None else 0, 'ltp': raw['lastPrice']})
    return {'status': 'OK', 'forward': p['forward'], 'T': p['T'], 'df': p['discountFactor'], 'atmStrike': p['atmStrike'], 'candleRefPrice': spot, 'resistances': [{'price': l['price'], 'touches': l['touches'], 'sources': list(l['sources'])} for l in lv['allResistance']], 'supports': [{'price': l['price'], 'touches': l['touches'], 'sources': list(l['sources'])} for l in lv['allSupport']], 'atr': lv['atr14'], 'barMinutes': lv['timeframeMinutes'], 'legs': legs, 'excludedLegs': excluded, 'snapshotMs': p['asOfMs'], 'candlesMs': candles[-1]['timestampMs'] if candles else None, 'gateWarnings': p['gate']['warnings']}

def run_refresh(scan: dict, now):
    if scan.get('status') != 'OK' or scan.get('candlesMs') is None:
        return (None, BLANK_TABLE)
    rt = _BX_RT
    rows = rt.build_refresh_table(forward=scan['forward'], T=scan['T'], df=scan['df'], candle_ref_price=scan['candleRefPrice'], resistances=[rt.Level(l['price'], l['touches'], l['sources']) for l in scan['resistances']], supports=[rt.Level(l['price'], l['touches'], l['sources']) for l in scan['supports']], atr=scan['atr'] if scan['atr'] is not None else 0.0, bar_minutes=int(scan['barMinutes']) if scan['barMinutes'] else 5, legs=[rt.Leg(l['strike'], l['isCall'], l['ivPct'], l['bid'], l['ask'], l['ltp']) for l in scan['legs']], snapshot_ms=scan['snapshotMs'], candles_ms=scan['candlesMs'], now=now)
    return (rows, rt.to_compact(rows))

def in_no_trade_window(now) -> bool:
    rt = _BX_RT
    return rt.in_skip_window(now)

