    def _request(self, method, path, body, unique_key, accept_bare) -> DhanResponse:
        cls = self.assert_read_only(method, path)
        headers = {'access-token': self._creds.access_token, 'client-id': self._creds.client_id, 'Content-Type': 'application/json', 'Accept': 'application/json'}
        if path == '/profile':
            headers['dhanClientId'] = self._creds.client_id
        data = json.dumps(body).encode() if body is not None else None
        last: DhanClientError | None = None
        for attempt in range(1, self.max_attempts + 1):
            self.limiter.acquire(cls, unique_key)
            try:
                raw = self.transport.send(method, self.base_url + path, headers, data, self.timeout_s)
            except Exception as e:
                last = TransientError('Network error on %s: %s' % (path, self.redact(type(e).__name__)))
            else:
                try:
                    return self._interpret(path, raw, attempt, accept_bare)
                except DhanClientError as e:
                    last = e
            if not last.retryable or attempt == self.max_attempts:
                last.attempts = attempt
                self._emit('error', 'request_failed', path=path, attempt=attempt, error=type(last).__name__, error_code=last.error_code, http_status=last.http_status, message=str(last))
                raise last
            wait = last.retry_after_s or min(20.0, 0.5 * 2 ** (attempt - 1)) * (0.5 + self.jitter() / 2)
            self._emit('warn', 'request_retry', path=path, attempt=attempt, error=type(last).__name__, error_code=last.error_code, wait_s=round(wait, 3))
            self.sleep(wait)
        raise last

    def _interpret(self, path: str, raw: RawResponse, attempt: int, accept_bare) -> DhanResponse:
        text = raw.body.decode('utf-8', errors='replace') if raw.body else ''
        try:
            parsed = json.loads(text) if text else {}
        except ValueError:
            if raw.status >= 500:
                raise TransientError('HTTP %d with non-JSON body on %s' % (raw.status, path), http_status=raw.status)
            raise ResponseFormatError('Non-JSON response on %s (HTTP %d)' % (path, raw.status), http_status=raw.status)
        ecode = ''
        msg = 'HTTP %d' % raw.status
        if isinstance(parsed, dict):
            ecode = str(parsed.get('errorCode') or parsed.get('internalErrorCode') or '').upper()
            msg = str(parsed.get('errorMessage') or parsed.get('internalErrorMessage') or msg)
        msg = self.redact(msg)
        if raw.status == 429 or ecode in THROTTLE_CODES:
            e = RateLimitedError('Throttled on %s: %s' % (path, msg), error_code=ecode, http_status=raw.status)
            ra = raw.headers.get('Retry-After') or raw.headers.get('retry-after')
            try:
                e.retry_after_s = float(ra) if ra else None
            except ValueError:
                e.retry_after_s = None
            raise e
        if ecode in PLAN_CODES:
            raise PlanError('Data API access missing on %s (%s): check the Data API plan in Dhan web; a new token will not fix this.' % (path, ecode), error_code=ecode, http_status=raw.status)
        if raw.status in (401, 403) or ecode in AUTH_CODES:
            raise AuthError('Dhan rejected the credentials on %s (%s). Generate a fresh token in Dhan web and update your local environment.' % (path, ecode or raw.status), error_code=ecode, http_status=raw.status)
        if raw.status >= 500 or ecode in RETRYABLE_CODES:
            raise TransientError('Dhan server error on %s: %s' % (path, msg), error_code=ecode, http_status=raw.status)
        if raw.status >= 400:
            raise RequestRejectedError('Dhan rejected the request on %s: %s (%s)' % (path, msg, ecode), error_code=ecode, http_status=raw.status)
        if isinstance(parsed, dict) and parsed.get('status') not in (None, 'success'):
            raise RequestRejectedError('Dhan returned status=%r on %s: %s' % (parsed.get('status'), path, msg), error_code=ecode)
        if isinstance(parsed, dict) and 'data' in parsed:
            return DhanResponse(path, parsed['data'], 'wrapped', raw.received_at_ms, attempt)
        if accept_bare is not None and accept_bare(parsed):
            return DhanResponse(path, parsed, 'bare', raw.received_at_ms, attempt)
        raise ResponseFormatError('Unrecognised response envelope on %s' % path)

    def expiry_list(self, scrip: int=51, segment: str='IDX_I') -> DhanResponse:
        return self.request('POST', '/optionchain/expirylist', {'UnderlyingScrip': scrip, 'UnderlyingSeg': segment}, unique_key='expirylist:%s:%s' % (segment, scrip), accept_bare=lambda p: isinstance(p, list))

    def option_chain(self, expiry: str, scrip: int=51, segment: str='IDX_I') -> DhanResponse:
        return self.request('POST', '/optionchain', {'UnderlyingScrip': scrip, 'UnderlyingSeg': segment, 'Expiry': expiry}, unique_key='%s:%s:%s' % (segment, scrip, expiry), accept_bare=lambda p: isinstance(p, dict) and 'oc' in p)

    def quote(self, instruments: dict) -> DhanResponse:
        total = sum((len(v) for v in instruments.values()))
        if total == 0 or total > 1000:
            raise RequestRejectedError('marketfeed/quote needs 1..1000 instruments, got %d' % total)
        return self.request('POST', '/marketfeed/quote', {k: list(v) for k, v in instruments.items()}, accept_bare=lambda p: isinstance(p, dict) and any((k in p for k in instruments)))

    def intraday_candles(self, security_id: str, segment: str, instrument: str, interval: int, from_datetime: str, to_datetime: str, oi: bool=False) -> DhanResponse:
        if interval not in (1, 5, 15, 25, 60):
            raise RequestRejectedError('interval must be 1, 5, 15, 25 or 60')
        return self.request('POST', '/charts/intraday', {'securityId': str(security_id), 'exchangeSegment': segment, 'instrument': instrument, 'interval': interval, 'oi': oi, 'fromDate': from_datetime, 'toDate': to_datetime}, accept_bare=lambda p: isinstance(p, dict) and 'timestamp' in p)

    def profile(self) -> DhanResponse:
        return self.request('GET', '/profile', None, accept_bare=lambda p: isinstance(p, dict))

    def daily_candles(self, security_id: str, segment: str, instrument: str, from_date: str, to_date: str, expiry_code: int=0, oi: bool=False) -> DhanResponse:
        return self.request('POST', '/charts/historical', {'securityId': str(security_id), 'exchangeSegment': segment, 'instrument': instrument, 'expiryCode': expiry_code, 'oi': oi, 'fromDate': from_date, 'toDate': to_date}, accept_bare=lambda p: isinstance(p, dict) and 'timestamp' in p)

