import hashlib
import json
import math

class DataValidationError(Exception):

    def __init__(self, error_code: str, message: str):
        super().__init__('%s: %s' % (error_code, message))
        self.error_code = error_code
        self.message = message

def _fin(v):
    return is_number(v) and math.isfinite(v)

def validate_expiry_list(payload) -> list:
    if not isinstance(payload, list):
        raise DataValidationError('EXPIRY_SCHEMA', 'expiry list is not a JSON array')
    good = [x for x in payload if is_iso_date(x)]
    if not good:
        raise DataValidationError('EXPIRY_EMPTY', 'expiry list has no YYYY-MM-DD dates')
    return sorted(good)

def validate_chain(payload, min_pairs: int=2) -> list:
    if not isinstance(payload, dict):
        raise DataValidationError('CHAIN_SCHEMA', 'option chain payload is not an object')
    oc = payload.get('oc')
    if not isinstance(oc, dict) or not oc:
        raise DataValidationError('CHAIN_EMPTY', "option chain has no 'oc' strikes")
    warnings = []
    if not _fin(payload.get('last_price')):
        warnings.append("CHAIN_NO_INDEX_LTP: 'last_price' missing; levels cannot be placed (table will show NO_LEVEL)")
    pairs, bad_keys = (0, 0)
    for key, v in oc.items():
        try:
            float(key)
        except (TypeError, ValueError):
            bad_keys += 1
            continue
        if not isinstance(v, dict):
            continue
        ce, pe = (v.get('ce'), v.get('pe'))
        if isinstance(ce, dict) and isinstance(pe, dict) and _fin(ce.get('last_price')) and _fin(pe.get('last_price')):
            pairs += 1
    if bad_keys:
        warnings.append('CHAIN_BAD_STRIKE_KEYS: %d non-numeric strike key(s) ignored' % bad_keys)
    if pairs < min_pairs:
        raise DataValidationError('CHAIN_INSUFFICIENT_PAIRS', '%d strike(s) with both CE and PE prices; parity needs %d' % (pairs, min_pairs))
    return warnings

def validate_quote(payload, segment: str, security_id) -> dict:
    if not isinstance(payload, dict):
        raise DataValidationError('QUOTE_SCHEMA', 'quote payload is not an object')
    seg = payload.get(segment)
    if not isinstance(seg, dict):
        raise DataValidationError('QUOTE_MISSING_SEGMENT', 'no %s block in quote response' % segment)
    q = seg.get(str(security_id))
    if not isinstance(q, dict):
        raise DataValidationError('QUOTE_MISSING_INSTRUMENT', 'no data for %s:%s' % (segment, security_id))
    if not _fin(q.get('last_price')):
        raise DataValidationError('QUOTE_NO_LTP', '%s:%s has no usable last_price' % (segment, security_id))
    return q

def validate_candles(payload) -> list:
    if not isinstance(payload, dict):
        raise DataValidationError('CANDLE_SCHEMA', 'candle payload is not an object')
    arrays = {k: payload.get(k) for k in ('timestamp', 'open', 'high', 'low', 'close')}
    if not all((isinstance(a, list) for a in arrays.values())):
        raise DataValidationError('CANDLE_SCHEMA', 'missing one of timestamp/open/high/low/close arrays')
    lengths = {k: len(a) for k, a in arrays.items()}
    warnings = []
    if len(set(lengths.values())) != 1:
        warnings.append('CANDLE_RAGGED: unequal array lengths %s; extra values dropped' % lengths)
    ts = arrays['timestamp']
    if any((_fin(b) and _fin(a) and (b <= a) for a, b in zip(ts, ts[1:]))):
        warnings.append('CANDLE_ORDER: timestamps not strictly increasing; candles are re-sorted')
    return warnings

def snapshot_fingerprint(chain_payload) -> str:
    return hashlib.sha256(json.dumps(chain_payload, sort_keys=True, separators=(',', ':')).encode()).hexdigest()[:16]

