import json
import sys
import threading
import time as _bx_scanner__time
from dataclasses import dataclass, field
from datetime import date, datetime, time as dtime, timedelta, timezone
SENSEX_SCRIP, SENSEX_SEG, FUT_SEG = (51, 'IDX_I', 'BSE_FNO')

class JsonLogger:

    def __init__(self, redactor: Redactor, stream=None, sink=None, clock=None, prefix: str=''):
        self.redact, self.stream, self.sink, self.prefix = (redactor, stream or sys.stderr, sink, prefix)
        self.clock = clock or (lambda: datetime.now(timezone.utc))

    def __call__(self, level: str, event: str, **fields):
        rec = {'ts': self.clock().astimezone(IST).isoformat(timespec='seconds'), 'level': level, 'event': event}
        rec.update(fields)
        line = self.redact(json.dumps(rec, default=str, ensure_ascii=False))
        self.stream.write(self.prefix + line + '\n')
        self.stream.flush()
        if self.sink is not None:
            self.sink(line)

@dataclass
class ScannerConfig:
    strikes: list
    interval_s: float = 60.0
    stop_time: dtime = DEFAULT_STOP
    holidays: frozenset = frozenset()
    futures_security_id: str | None = None
    futures_expiry: str | None = None
    instrument_contracts: list | None = None
    candle_interval: int = 5
    risk_free_rate: float = 0.065
    max_snapshot_skew_ms: float = 3000
    max_scans: int | None = None
    ignore_session: bool = False
    min_interval_s: float = 10.0
    observe: bool = True
    observe_leg_band: int = 5
    extra_series: bool = False
    poll_s: float = 5.0

@dataclass
class ScanState:
    scans: int = 0
    last_fingerprint: str | None = None
    stop_reason: str | None = None
    history: list = field(default_factory=list)

class Scanner:

    def __init__(self, client, config: ScannerConfig, log, clock=None, sleep=_bx_scanner__time.sleep):
        if not config.strikes:
            raise ValueError('strikes are required: ATM±2 selection is not defined yet (docs/PHASE4_PORT_PLAN.md P1)')
        if config.interval_s < config.min_interval_s:
            raise ValueError('interval must be >= %ss (Dhan option-chain limit is 1 per 3 s)' % config.min_interval_s)
        self.client, self.cfg, self.log = (client, config, log)
        self.clock = clock or (lambda: datetime.now(timezone.utc))
        self.sleep = sleep
        self.state = ScanState()
        self.stop_event = threading.Event()
        self.poller = None

    def _future(self, option_expiry: date, today: date):
        if self.cfg.instrument_contracts is not None:
            return select_future(self.cfg.instrument_contracts, option_expiry, today)
        if not self.cfg.futures_security_id or not self.cfg.futures_expiry:
            raise InstrumentResolutionError('No futures contract: pass --futures-security-id and --futures-expiry (automatic lookup is BLOCKED until the instrument-master header is verified).')
        return explicit_future(self.cfg.futures_security_id, self.cfg.futures_expiry, today, option_expiry)

    def run_once(self) -> dict:
        now = self.clock()
        ist = now.astimezone(IST)
        self.state.scans += 1
        rec = {'scan': self.state.scans, 'scanId': '%s-%04d' % (ist.strftime('%Y%m%d'), self.state.scans), 'startedIst': ist.isoformat(timespec='seconds'), 'clockUtc': now.astimezone(timezone.utc).isoformat(timespec='milliseconds'), 'status': None, 'warnings': [], 'envelopes': {}, 'table': BLANK_TABLE}
        calls, detail, rows = ([], {}, None)
        if self.cfg.observe and hasattr(self.client, 'on_call'):
            self.client.on_call = calls.append
        try:
            rec['session'] = self._session_label(ist)
            rows = self._scan(rec, now, ist, detail)
        except (AuthError, PlanError) as e:
            rec.update(status='AUTH_FAILED' if isinstance(e, AuthError) else 'PLAN_MISSING', reason=str(e))
            self.state.stop_reason = rec['status']
            self.stop_event.set()
        except InstrumentResolutionError as e:
            rec.update(status='CONFIG_BLOCKED', reason=str(e))
        except (DataValidationError, ExpirySelectionError) as e:
            rec.update(status='INVALID_DATA', reason=str(e))
        except DhanClientError as e:
            rec.update(status='ERROR', reason='%s: %s' % (type(e).__name__, e))
        finally:
            if hasattr(self.client, 'on_call'):
                self.client.on_call = None
        if self.poller is not None and rec['status'] not in ('AUTH_FAILED', 'PLAN_MISSING'):
            self.poller.after_scan(rec, detail, rows)
        if self.cfg.observe:
            dur = (self.clock() - now).total_seconds() * 1000
            nxt = None
            if not self.stop_event.is_set() and (self.cfg.max_scans is None or self.state.scans < self.cfg.max_scans):
                n = (now + timedelta(seconds=self.cfg.interval_s)).astimezone(IST)
                nxt = n.isoformat(timespec='seconds') if self.cfg.ignore_session or n.time() < self.cfg.stop_time else 'none (stop time %s)' % self.cfg.stop_time.isoformat()
            rec['observation'] = build_observation(rec=rec, detail=detail, endpoints=calls, rows=rows, contract=rec.get('futures'), next_scan_ist=nxt, duration_ms=dur, leg_band=self.cfg.observe_leg_band)
        return self._finish(rec)

    def _session_label(self, ist) -> str:
        t = ist.time()
        if t < dtime(9, 15):
            return 'PRE_OPEN'
        if t < dtime(9, 25):
            return 'OPENING (no-trade window to 09:25)'
        if dtime(11, 30) <= t < dtime(13, 0):
            return 'MIDDAY (no-trade window 11:30-13:00)'
        if t >= dtime(14, 50):
            return 'CLOSING (no-trade window after 14:50)'
        return 'MORNING' if t < dtime(11, 30) else 'AFTERNOON'

    def _scan(self, rec, now, ist, detail):
        st = session_state(now, self.cfg.holidays, self.cfg.stop_time)
        if not st.open and (not self.cfg.ignore_session):
            rec.update(status='SKIPPED', reason=st.reason)
            return None
        today = ist.date()
        exp_resp = self.client.expiry_list(SENSEX_SCRIP, SENSEX_SEG)
        rec['envelopes']['expirylist'] = exp_resp.envelope
        expiries = validate_expiry_list(exp_resp.payload)
        expiry = next_after(expiries, today.isoformat(), '%s:%d' % (SENSEX_SEG, SENSEX_SCRIP))
        rec['expiry'] = expiry
        fut = self._future(date.fromisoformat(expiry), today)
        rec['futures'] = {'securityId': fut.security_id, 'expiry': fut.expiry.isoformat()}
        chain = self.client.option_chain(expiry, SENSEX_SCRIP, SENSEX_SEG)
        quote = self.client.quote({FUT_SEG: [int(fut.security_id)]})
        rec['envelopes'].update(optionchain=chain.envelope, quote=quote.envelope)
        rec['warnings'] += validate_chain(chain.payload)
        fp = snapshot_fingerprint(chain.payload)
        if fp == self.state.last_fingerprint:
            rec['warnings'].append('DUPLICATE_SNAPSHOT: option chain identical to the previous scan (feed may be stale, or the market is closed/halted)')
        self.state.last_fingerprint = fp
        rec['chainFingerprint'] = fp
        try:
            raw_fut = validate_quote(quote.payload, FUT_SEG, fut.security_id)
        except DataValidationError as e:
            raw_fut = None
            rec['warnings'].append(e.error_code + ': ' + e.message)
        day = today.isoformat()
        candles = []
        try:
            cnd = self.client.intraday_candles(str(SENSEX_SCRIP), SENSEX_SEG, 'INDEX', self.cfg.candle_interval, day + ' 09:15:00', day + ' 15:30:00')
            rec['envelopes']['intraday'] = cnd.envelope
            rec['warnings'] += validate_candles(cnd.payload)
            candles = to_candles(cnd.payload)
        except (AuthError, PlanError):
            raise
        except DataValidationError as e:
            rec['warnings'].append(e.error_code + ': ' + e.message)
        except DhanClientError as e:
            rec['warnings'].append('CANDLES_UNAVAILABLE: %s: %s' % (type(e).__name__, e))
        if not candles:
            rec['warnings'].append('NO_CANDLES: no index candles for today (holiday, pre-open, or feed issue); levels cannot be derived')
        if self.cfg.extra_series:
            detail['fut1m'] = self._optional_candles(rec, fut.security_id, FUT_SEG, 'FUTIDX', day, 'FUT_1M')
            detail['idx1m'] = self._optional_candles(rec, str(SENSEX_SCRIP), SENSEX_SEG, 'INDEX', day, 'INDEX_1M')
        scan = build_scan(raw_chain=chain.payload, raw_futures=raw_fut, candles=candles, expiry=expiry, strikes=self.cfg.strikes, chain_received_ms=chain.received_at_ms, futures_received_ms=quote.received_at_ms, futures_security_id=fut.security_id, futures_expiry=fut.expiry.isoformat(), risk_free_rate=self.cfg.risk_free_rate, max_snapshot_skew_ms=self.cfg.max_snapshot_skew_ms, detail_out=detail)
        rows, table = run_refresh(scan, ist)
        rec.update(status=scan['status'], table=table, scanInputs=scan)
        if scan['status'] == 'OK':
            rec.update(forward=scan['forward'], atmStrike=scan['atmStrike'], rowStatuses=sorted({r.status for r in rows}) if rows else [], excludedLegs=scan['excludedLegs'])
        else:
            rec['reason'] = ' | '.join(scan.get('reasons', []))
        return rows

    def _optional_candles(self, rec, security_id, segment, instrument, day, label):
        try:
            r = self.client.intraday_candles(str(security_id), segment, instrument, 1, day + ' 09:15:00', day + ' 15:30:00')
            validate_candles(r.payload)
            return to_candles(r.payload)
        except (AuthError, PlanError):
            raise
        except (DhanClientError, DataValidationError) as e:
            rec['warnings'].append('%s_UNAVAILABLE: %s' % (label, type(e).__name__))
            return []

    def _finish(self, rec: dict) -> dict:
        rec['finishedIst'] = self.clock().astimezone(IST).isoformat(timespec='seconds')
        self.state.history.append(rec['status'])
        self.log('info' if rec['status'] in ('OK', 'SKIPPED') else 'warn', 'scan', **{k: v for k, v in rec.items() if k != 'scanInputs'})
        return rec

    def request_stop(self, reason: str='SIGNAL') -> None:
        self.state.stop_reason = self.state.stop_reason or reason
        self.stop_event.set()

    def run_loop(self, on_record=None) -> str:
        self.log('info', 'scanner_start', interval_s=self.cfg.interval_s, stop=self.cfg.stop_time.isoformat(), strikes=self.cfg.strikes, max_scans=self.cfg.max_scans)
        while not self.stop_event.is_set():
            st = session_state(self.clock(), self.cfg.holidays, self.cfg.stop_time)
            if not st.open and (not self.cfg.ignore_session):
                self.state.stop_reason = self.state.stop_reason or 'SESSION_' + st.reason
                break
            tick = self.clock()
            rec = self.run_once()
            if on_record:
                on_record(rec)
            if self.stop_event.is_set():
                break
            if self.cfg.max_scans is not None and self.state.scans >= self.cfg.max_scans:
                self.state.stop_reason = 'MAX_SCANS'
                break
            remaining = self.cfg.interval_s - (self.clock() - tick).total_seconds()
            last_poll = self.clock()
            while remaining > 0 and (not self.stop_event.is_set()):
                step = min(1.0, remaining)
                self.sleep(step)
                remaining -= step
                if self.poller is not None and remaining > 1.0 and ((self.clock() - last_poll).total_seconds() >= self.cfg.poll_s):
                    t0 = self.clock()
                    if not self.poller.tick():
                        self.state.stop_reason = 'AUTH_FAILED'
                        self.stop_event.set()
                    last_poll = self.clock()
                    remaining -= (last_poll - t0).total_seconds()
        if self.poller is not None:
            self.poller.tracker.close_all(int(self.clock().timestamp() * 1000))
            self.log('info', 'paper_summary', **self.poller.tracker.summary())
        reason = self.state.stop_reason or 'STOPPED'
        self.log('info', 'scanner_stop', reason=reason, scans=self.state.scans, statuses=self.state.history)
        return reason

