MODE = "VALIDATE"                 # "VALIDATE" | "CHECKS" | "PROFILE_CHECK" | "INSTRUMENTS" | "LIVE_CHECK" | "OBSERVE"

# Strikes shown in the refresh table. Explicit, because the ATM±2 rule is not
# defined yet (PHASE4_PORT_PLAN P1). Each scan logs atmStrike to help you pick.
STRIKES = []                      # e.g. [81000, 81100, 81200, 81300, 81400]

# SENSEX future used ONLY for the data-gate cross-check. Verify the id and
# expiry in Dhan web or the instrument master before use. Never guessed here.
FUTURES_SECURITY_ID = ""          # e.g. "864571" (REPORTED OCT contract: re-verify)
FUTURES_EXPIRY = ""               # "YYYY-MM-DD"; refused once expired

INTERVAL_S = 60                   # seconds between scans (minimum 10)
STOP_TIME = "15:30"               # IST; the loop ends here
HOLIDAYS = []                     # exchange holidays you maintain, "YYYY-MM-DD"
RECORD_EVERY_N = 15               # replay record every N scans (plus every non-OK scan); 0 = off
RECORD_CHUNK = 3000               # characters per replay-record log line
LEG_BAND = 5                      # strikes either side of ATM logged with IV/Greeks/OI/bid-ask
                                  # (lower it if decode_cloud_log reports truncated lines)
EXTRA_SERIES = True               # 1-min index + 1-min futures candles: VWAP, volume, 1-min close facts

# PAPER tracker (NO orders): when the index crosses an OK refresh-table trigger,
# record a virtual entry at the option ASK and follow the BID until one exit hits.
PAPER_ENABLED = True
PAPER_TAKE_PROFIT_PTS = 6         # your rule (9 Oct 2026), option premium points
PAPER_STOP_LOSS_PTS = 11          # your rule (9 Oct 2026), option premium points
PAPER_TIME_STOP_MIN = 10          # RULES.md §6 time stop
POLL_S = 5                        # seconds between fast read-only price polls (min 2)
