import gzip
import json
import sys
import urllib.request
import time as _bx_main__time
from datetime import datetime, time as dtime, timezone
PROGRAM = 'sensex-readonly-observer'
VERSION = '6.9'
EXIT_OK, EXIT_CONFIG, EXIT_AUTH, EXIT_SELFTEST = (0, 2, 3, 4)

def _stdout_logger(redactor):
    return JsonLogger(redactor, stream=sys.stdout, prefix='BX|')

def _runtime(log):
    log('info', 'runtime', program=PROGRAM, version=VERSION, mode=MODE, python='%d.%d.%d' % tuple(sys.version_info[:3]), utc=datetime.now(timezone.utc).isoformat(timespec='seconds'), allowList=sorted(('%s %s' % k for k in READ_ONLY_ENDPOINTS)), orders='NONE (no order functions exist in this program)')

class _FixedTransport:

    def __init__(self, bodies, receipts, default_ms):
        self.bodies, self.receipts, self.default_ms = (bodies, receipts, default_ms)

    def send(self, method, url, headers, body, timeout):
        path = url.split('/v2', 1)[1]
        if path not in self.bodies:
            return RawResponse(404, b'{}', {}, self.default_ms)
        return RawResponse(200, json.dumps(self.bodies[path]).encode(), {}, self.receipts.get(path, self.default_ms))

def validate(log) -> int:
    st = SELFTEST
    t = _FixedTransport(st['bodies'], {k: int(v) for k, v in st['receipts'].items()}, int(st['receipts']['/optionchain']))
    sim = [0.0]
    lim = RateLimiter(clock=lambda: sim[0], sleep=lambda s: sim.__setitem__(0, sim[0] + s))
    red = Redactor()
    client = DhanClient(Credentials('SELFTEST', 'selftest-not-a-credential'), transport=t, limiter=lim, redactor=red, sleep=lambda s: None)
    at = datetime.fromisoformat(st['clockUtc'])
    cfg = ScannerConfig(strikes=st['strikes'], futures_security_id=st['futuresSecurityId'], futures_expiry=st['futuresExpiry'], ignore_session=True, max_scans=1)

    class _Quiet:

        def __call__(self, *a, **k):
            pass
    rec = Scanner(client, cfg, _Quiet(), clock=lambda: at).run_once()
    ok = rec['status'] == 'OK' and rec['table'] == st['expectedTable']
    log('info' if ok else 'error', 'selftest', data='MOCK (embedded Stage A s21Sep; not market data)', result='PASS' if ok else 'FAIL', status=rec['status'], table=rec['table'], observationKeys=sorted(rec.get('observation', {}).keys()))
    paper_ok = _paper_selftest()
    log('info' if paper_ok else 'error', 'paper_selftest', result='PASS' if paper_ok else 'FAIL', data='synthetic ticks (not market data)')
    ok = ok and paper_ok
    log('info', 'credential_placeholders', **_placeholder_status())
    return EXIT_OK if ok else EXIT_SELFTEST

def _paper_selftest() -> bool:
    events = []

    class _Row:

        def __init__(self, strike, side, trigger):
            self.strike, self.side, self.trigger, self.status = (strike, side, trigger, 'OK')
    t = PaperTracker(PaperConfig(take_profit_pts=6, stop_loss_pts=11), lambda *a, **k: events.append((a, k)), in_no_trade_window)
    t.arm([_Row(100.0, 'CE', 1000.0), _Row(100.0, 'PE', 990.0)], {(100.0, 'CE'): '1', (100.0, 'PE'): '2'}, True)
    base = int(datetime(2026, 9, 21, 4, 30, tzinfo=timezone.utc).timestamp() * 1000)
    t.on_tick(base, 995.0, {'1': (49.0, 50.0), '2': (59.0, 60.0)})
    t.on_tick(base + 5000, 1001.0, {'1': (49.5, 50.0), '2': (58.0, 59.0)})
    t.on_tick(base + 10000, 1004.0, {'1': (56.0, 56.5), '2': (55.0, 56.0)})
    t.on_tick(base + 15000, 989.0, {'1': (40.0, 41.0), '2': (70.0, 71.0)})
    t.on_tick(base + 20000, 999.0, {'1': (50.0, 51.0), '2': (59.0, 60.0)})
    out = [r['outcome'] for r in t.closed]
    return out == ['TAKE_PROFIT', 'STOP_LOSS'] and t.closed[0]['pnlPts'] == 6.0 and (t.closed[1]['pnlPts'] == -12.0)

def _filled(value: str) -> bool:
    return bool(value) and (not (value.startswith('{' + '{') and value.endswith('}' + '}')))

def _placeholder_status() -> dict:
    return {'CLIENT_ID': 'filled' if _filled(CLIENT_ID) else 'NOT filled', 'ACCESS_TOKEN': 'filled' if _filled(ACCESS_TOKEN) else 'NOT filled'}

def _config_errors():
    errs = []
    if not STRIKES:
        errs.append('STRIKES is empty (ATM±2 rule undefined; list strikes explicitly)')
    if not FUTURES_SECURITY_ID or not FUTURES_EXPIRY:
        errs.append('FUTURES_SECURITY_ID / FUTURES_EXPIRY not set (automatic lookup is BLOCKED)')
    if INTERVAL_S < 10:
        errs.append('INTERVAL_S must be >= 10')
    if PAPER_ENABLED and POLL_S < 2:
        errs.append('POLL_S must be >= 2 (quote endpoint limit is 1 request per second)')
    return errs

def _emit_record(scanner_rec, recorder, cfg, clock_utc, log_line):
    payload = {'scanId': scanner_rec['scanId'], 'meta': {'strikes': cfg.strikes, 'futuresSecurityId': cfg.futures_security_id, 'futuresExpiry': cfg.futures_expiry, 'clockUtc': clock_utc}}
    payload.update(recorder.take())
    blob = gzip.compress(json.dumps(payload).encode('utf-8')).hex()
    parts = [blob[i:i + RECORD_CHUNK] for i in range(0, len(blob), RECORD_CHUNK)] or ['']
    for i, part in enumerate(parts, 1):
        log_line('BX|REC|%s|%d/%d|%s' % (scanner_rec['scanId'], i, len(parts), part))
INSTRUMENT_FILE = 'https://images.dhan.co/api-data/api-scrip-master.csv'

def instruments(log) -> int:
    req = urllib.request.Request(INSTRUMENT_FILE, method='GET', headers={'User-Agent': 'sensex-readonly-observer'})
    header, rows, total = (None, [], 0)
    with urllib.request.urlopen(req, timeout=120) as resp:
        for raw in resp:
            text = raw.decode('utf-8', 'replace').rstrip('\r\n')
            if header is None:
                header = text
                continue
            total += 1
            up = text.upper()
            if 'SENSEX' in up and 'FUT' in up and (len(rows) < 20):
                rows.append(text)
    log('info', 'instrument_file', source=INSTRUMENT_FILE, header=header, rowsScanned=total, sensexFutureRows=rows, note='public data; verify the contract before use')
    return EXIT_OK if header else EXIT_CONFIG

def _managed_credentials(log, redactor):
    if not (_filled(CLIENT_ID) and _filled(ACCESS_TOKEN)):
        log('error', 'credentials_missing', placeholders=_placeholder_status(), action='Dhan Cloud did not substitute the two credential placeholders: check the account connection on the Cloud home screen')
        return None
    creds = Credentials(CLIENT_ID.strip(), ACCESS_TOKEN.strip())
    redactor.register(creds.access_token, creds.client_id)
    exp = creds.token_expiry_ms()
    now_ms = _bx_main__time.time() * 1000
    if exp is not None and exp <= now_ms:
        log('error', 'token_expired', hours_ago=round((now_ms - exp) / 3600000.0, 2), action='The managed access token has expired: re-connect / refresh the Dhan account in Dhan Cloud')
        return None
    log('info', 'token_status', hours_left=None if exp is None else round((exp - now_ms) / 3600000.0, 2))
    return creds

def profile_check(log, redactor) -> int:
    creds = _managed_credentials(log, redactor)
    if creds is None:
        return EXIT_AUTH
    client = DhanClient(creds, transport=UrllibTransport(), redactor=redactor, logger=log)
    try:
        r = client.profile()
    except DhanClientError as e:
        log('error', 'profile_check_failed', error=type(e).__name__, errorCode=e.error_code, httpStatus=e.http_status)
        return EXIT_AUTH
    body = r.payload if isinstance(r.payload, dict) else {}
    log('info', 'profile_check', ok=True, envelope=r.envelope, fieldsPresent=sorted(body.keys()), dataPlan=body.get('dataPlan'), dataValidity=body.get('dataValidity'), tokenValidity=body.get('tokenValidity'))
    return EXIT_OK

def live(log, redactor, loop: bool) -> int:
    errs = _config_errors()
    if errs:
        log('error', 'config_blocked', errors=errs)
        return EXIT_CONFIG
    if not (_filled(CLIENT_ID) and _filled(ACCESS_TOKEN)):
        log('error', 'credentials_missing', placeholders=_placeholder_status(), action='Dhan Cloud did not substitute the two credential placeholders: check the account connection on the Cloud home screen')
        return EXIT_AUTH
    creds = Credentials(CLIENT_ID.strip(), ACCESS_TOKEN.strip())
    redactor.register(creds.access_token, creds.client_id)
    exp = creds.token_expiry_ms()
    now_ms = _bx_main__time.time() * 1000
    if exp is not None and exp <= now_ms:
        log('error', 'token_expired', hours_ago=round((now_ms - exp) / 3600000.0, 2), action='The managed access token has expired: re-connect / refresh the Dhan account in Dhan Cloud')
        return EXIT_AUTH
    log('info', 'token_status', hours_left=None if exp is None else round((exp - now_ms) / 3600000.0, 2))
    recorder = MemoryRecorder(UrllibTransport())
    client = DhanClient(creds, transport=recorder, redactor=redactor, logger=log)
    hh, mm = (int(x) for x in STOP_TIME.split(':'))
    cfg = ScannerConfig(strikes=[float(s) for s in STRIKES], interval_s=float(INTERVAL_S), stop_time=dtime(hh, mm), holidays=frozenset(HOLIDAYS), futures_security_id=str(FUTURES_SECURITY_ID), futures_expiry=FUTURES_EXPIRY, max_scans=None if loop else 1, observe_leg_band=int(LEG_BAND), extra_series=bool(EXTRA_SERIES), poll_s=float(POLL_S))
    scanner = Scanner(client, cfg, log)
    if PAPER_ENABLED and loop:
        tracker = PaperTracker(PaperConfig(take_profit_pts=float(PAPER_TAKE_PROFIT_PTS), stop_loss_pts=float(PAPER_STOP_LOSS_PTS), time_stop_s=float(PAPER_TIME_STOP_MIN) * 60, lot_size=LOT_SIZE, cost_per_trade_rs=COST_PER_TRADE_RS), log, in_no_trade_window)
        scanner.poller = FastPoller(client, tracker, log, cfg.strikes)

    def line(text):
        sys.stdout.write(redactor(text) + '\n')
        sys.stdout.flush()

    def on_record(rec):
        n = rec['scan']
        if RECORD_EVERY_N and rec['status'] != 'SKIPPED' and (rec['status'] != 'OK' or n == 1 or n % RECORD_EVERY_N == 0):
            _emit_record(rec, recorder, cfg, rec['clockUtc'], line)
        else:
            recorder.take()
    reason = scanner.run_loop(on_record=on_record)
    h = scanner.state.history
    log('info', 'session_summary', stopReason=reason, scans=len(h), statusCounts={s: h.count(s) for s in sorted(set(h))}, ordersPlaced=0, strategy='NO_SIGNAL (direction thresholds not configured)')
    return EXIT_AUTH if reason in ('AUTH_FAILED', 'PLAN_MISSING') else EXIT_OK

def main() -> int:
    redactor = Redactor()
    log = _stdout_logger(redactor)
    _runtime(log)
    if MODE == 'VALIDATE':
        return validate(log)
    if MODE == 'PROFILE_CHECK':
        return profile_check(log, redactor)
    if MODE == 'CHECKS':
        a = profile_check(log, redactor)
        b = instruments(log)
        return a or b
    if MODE == 'INSTRUMENTS':
        return instruments(log)
    if MODE in ('LIVE_CHECK', 'OBSERVE'):
        return live(log, redactor, loop=MODE == 'OBSERVE')
    log('error', 'config_blocked', errors=['MODE must be VALIDATE, CHECKS, PROFILE_CHECK, INSTRUMENTS, LIVE_CHECK or OBSERVE'])
    return EXIT_CONFIG
if __name__ == '__main__':
    main()
